template <class T, class charT = char, class traits = char_traits<charT>, class Distance = ptrdiff_t>
class istream_iterator {
public:
    // Default constructor creates an end-of-stream iterator
    istream_iterator();
    // Constructor that initializes the iterator with an input stream
    explicit istream_iterator(std::basic_istream<charT, traits>& s);
    // Dereference operator to access the current element
    T operator*() const;
    // Pre-increment operator to read the next element
    istream_iterator& operator++();
    // Post-increment operator
    istream_iterator operator++(int);
    // Equality comparison (to check for end-of-stream)
    bool operator==(const istream_iterator& other) const;
    bool operator!=(const istream_iterator& other) const;
};
